attributes.visState:
{"title": "[Tropobeat] CCI ops: episodes per day, 14 days", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "legend": {
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 11.5,
   "symbolType": "square",
   "symbolSize": 100,
   "symbolStrokeWidth": 0,
   "columnPadding": 14,
   "layout": {
    "top": {
     "anchor": "end"
    }
   }
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  }
 },
 "title": {
  "text": "Episodes per day, 14 days",
  "subtitle": {
   "signal": "'EPISODES BY START DAY · ' + 'LOCAL TIME (UTC' + timeFormat(now(), '%Z') + ')'"
  },
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "ax",
   "value": 18
  },
  {
   "name": "foot",
   "value": 24
  },
  {
   "name": "ch",
   "update": "max(40, height - ax - foot)"
  },
  {
   "name": "avg",
   "update": "length(data('past')) ? data('past')[0].m : 0"
  }
 ],
 "data": [
  {
   "name": "epStarts",
   "format": {
    "property": "aggregations.e.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "e": {
       "terms": {
        "field": "tropobeat.correlation.episode.id",
        "size": 10000
       },
       "aggs": {
        "start": {
         "min": {
          "field": "@timestamp"
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "gte": "now-15d"
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   },
   "transform": [
    {
     "type": "formula",
     "as": "day",
     "expr": "+datetime(year(datum.start.value), month(datum.start.value), date(datum.start.value))"
    },
    {
     "type": "aggregate",
     "groupby": [
      "day"
     ],
     "as": [
      "n"
     ]
    }
   ]
  },
  {
   "name": "days",
   "transform": [
    {
     "type": "sequence",
     "start": 0,
     "stop": 14,
     "as": "i"
    },
    {
     "type": "formula",
     "as": "key",
     "expr": "+datetime(year(now()), month(now()), date(now()) - 13 + datum.i)"
    },
    {
     "type": "lookup",
     "from": "epStarts",
     "key": "day",
     "fields": [
      "key"
     ],
     "values": [
      "n"
     ],
     "default": 0
    },
    {
     "type": "formula",
     "as": "back",
     "expr": "14 - datum.i"
    },
    {
     "type": "formula",
     "as": "today",
     "expr": "datum.i == 13"
    },
    {
     "type": "extent",
     "field": "n",
     "signal": "next"
    }
   ]
  },
  {
   "name": "past",
   "source": "days",
   "transform": [
    {
     "type": "filter",
     "expr": "!datum.today"
    },
    {
     "type": "aggregate",
     "fields": [
      "n"
     ],
     "ops": [
      "mean"
     ],
     "as": [
      "m"
     ]
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "x",
   "type": "band",
   "domain": {
    "data": "days",
    "field": "key",
    "sort": true
   },
   "range": "width",
   "paddingInner": 0.3
  },
  {
   "name": "y",
   "type": "linear",
   "nice": true,
   "zero": true,
   "domain": {
    "signal": "[0, max(4, next[1] || 0, avg)]"
   },
   "range": [
    {
     "signal": "ch"
    },
    0
   ]
  }
 ],
 "marks": [
  {
   "type": "rect",
   "from": {
    "data": "days"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key"
     },
     "width": {
      "scale": "x",
      "band": 1
     },
     "y": {
      "scale": "y",
      "field": "n"
     },
     "y2": {
      "scale": "y",
      "value": 0
     },
     "fill": {
      "signal": "datum.today ? '#FF6B5E' : 'rgba(255,107,94,0.45)'"
     },
     "cornerRadiusTopLeft": {
      "value": 2
     },
     "cornerRadiusTopRight": {
      "value": 2
     },
     "tooltip": {
      "signal": "{title: datum.today ? 'Today so far' : timeFormat(datum.key, '%a %d %b'), 'Episodes': datum.n}"
     }
    },
    "hover": {
     "fill": {
      "value": "#FF8A80"
     }
    }
   }
  },
  {
   "type": "rule",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "signal": "ch + 0.5"
     },
     "stroke": {
      "value": "#22384A"
     }
    }
   }
  },
  {
   "type": "rule",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "scale": "y",
      "signal": "avg"
     },
     "stroke": {
      "value": "#8DA2B2"
     },
     "strokeDash": {
      "value": [
       4,
       3
      ]
     },
     "opacity": {
      "signal": "avg > 0 ? 0.7 : 0"
     }
    }
   }
  },
  {
   "type": "rect",
   "encode": {
    "update": {
     "x2": {
      "signal": "width"
     },
     "width": {
      "signal": "length('AVG ' + format(avg, '.1f')) * 11 * 0.62 + 8"
     },
     "y": {
      "signal": "scale('y', avg) - 17"
     },
     "height": {
      "value": 15
     },
     "fill": {
      "value": "#0F1F2C"
     },
     "opacity": {
      "signal": "avg > 0 ? 1 : 0"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "signal": "width - 4"
     },
     "y": {
      "signal": "scale('y', avg) - 5"
     },
     "align": {
      "value": "right"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11
     },
     "fill": {
      "value": "#C3D1DB"
     },
     "text": {
      "signal": "avg > 0 ? 'AVG ' + format(avg, '.1f') : ''"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "days"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key",
      "band": {
       "signal": "datum.back == 14 ? 0 : datum.today ? 1 : 0.5"
      }
     },
     "y": {
      "signal": "ch + 5"
     },
     "align": {
      "signal": "datum.back == 14 ? 'left' : datum.today ? 'right' : 'center'"
     },
     "baseline": {
      "value": "top"
     },
     "text": {
      "signal": "datum.today ? 'TODAY' : datum.back == 14 || datum.back == 7 ? upper(timeFormat(datum.key, '%-d %b')) : ''"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "days"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "ch + ax + 16"
     },
     "fontSize": {
      "value": 13
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "datum.today ? 'Today so far: ' + datum.n + (datum.n == 1 ? ' episode' : ' episodes') + ' by ' + timeFormat(now(), '%H:%M') : ''"
     }
    }
   }
  }
 ]
}"}}
